// =====================================================
// 1. SAFE DATA INPUTS (CRASH-PROOF)
// =====================================================
// We use Optional Chaining (?.) so if a node fails, the code doesn't break.
const screenerData = $node["HTTP Request1"]?.json?.data || "";
const yahooQuote = $node["HTTP Request2"]?.json?.quoteResponse?.result?.[0] || {};
const yahooChart = $node["HTTP Request"]?.json?.chart?.result?.[0] || {};
const yahooPrices = yahooChart?.indicators?.quote?.[0]?.close || [];

// =====================================================
// 2. PARSING FUNCTIONS
// =====================================================
function extractBetween(start, end) {
  if (!screenerData) return null;
  const s = screenerData.indexOf(start);
  if (s === -1) return null;
  const sub = screenerData.substring(s + start.length);
  const e = sub.indexOf(end);
  return (e === -1) ? null : sub.substring(0, e).trim();
}

function extractTopRatio(label) {
  if (!screenerData) return null;
  const regex = new RegExp(`${label}[\\s\\S]*?<span class="number">([0-9,.]+)`, "i");
  const match = screenerData.match(regex);
  return match ? parseFloat(match[1].replace(/,/g, "")) : null;
}

function getColIndexForYear(tableId, yearStr) {
  if (!screenerData) return -1;
  const headerRegex = new RegExp(`section id="${tableId}"[\\s\\S]*?<thead>[\\s\\S]*?<tr>([\\s\\S]*?)<\\/tr>`, "i");
  const match = screenerData.match(headerRegex);
  if (!match) return -1;
  const headers = [...match[1].matchAll(/<th[^>]*>(.*?)<\/th>/gi)].map(m => m[1].replace(/<[^>]+>/g, "").trim());
  return headers.findIndex(h => h.includes(yearStr));
}

function extractTableData(tableId, rowNames, colIndex) {
  if (!screenerData) return 0;
  if (!Array.isArray(rowNames)) rowNames = [rowNames];

  const tableRegex = new RegExp(`section id="${tableId}"[\\s\\S]*?<table[\\s\\S]*?<\\/table>`, "i");
  const tableMatch = screenerData.match(tableRegex);
  if (!tableMatch) return 0;

  let rowMatch = null;
  for (const name of rowNames) {
    const rowRegex = new RegExp(`<tr[^>]*>[\\s\\S]*?${name}[\\s\\S]*?<\\/tr>`, "i");
    rowMatch = tableMatch[0].match(rowRegex);
    if (rowMatch) break;
  }

  if (!rowMatch) return 0;
  const cols = [...rowMatch[0].matchAll(/<td[^>]*>(.*?)<\/td>/gi)].map(m => m[1].replace(/<[^>]+>/g, "").trim());
  const idx = colIndex < 0 ? cols.length + colIndex : colIndex;
  return parseFloat(cols[idx]?.replace(/,/g, "")) || 0;
}

// Math Helpers
const calcCAGR = (s, e, years) => (s > 0 && e > 0) ? (Math.pow(e / s, 1 / years) - 1) * 100 : 0;
const calcReturn = (days) => {
  if (yahooPrices.length < days + 1) return 0;
  const curr = yahooPrices[yahooPrices.length - 1];
  const past = yahooPrices[yahooPrices.length - 1 - days];
  return (past && curr) ? ((curr - past) / past) * 100 : 0;
};
const calcMargin = (num, den) => den ? (num / den) * 100 : 0;

// =====================================================
// 3. EXTRACTION ENGINE
// =====================================================

// --- Identity ---
const companyName = yahooQuote.longName || extractBetween('<h1 class="margin-0 show-from-tablet-landscape">', '</h1>');
const nseCode = yahooQuote.symbol?.replace(".NS", "") || extractBetween("NSE:", "</span>")?.replace(/[^A-Z0-9]/g, "");

// --- Live Market Data ---
const price = yahooQuote.regularMarketPrice || extractTopRatio("Current Price") || 0;
const mCapCr = extractTopRatio("Market Cap"); // Keep in Crores from Screener
const vol = yahooQuote.regularMarketVolume || 0;
const high52 = yahooQuote.fiftyTwoWeekHigh || parseFloat(extractTopRatio("High / Low")?.toString().split("/")[0]?.replace(/,/g, "")) || 0;
const low52 = yahooQuote.fiftyTwoWeekLow || parseFloat(extractTopRatio("High / Low")?.toString().split("/")[1]?.replace(/,/g, "")) || 0;

// --- Analyst Consensus (From Node 2) ---
const targetMean = yahooQuote.targetMeanPrice || 0;
const targetHigh = yahooQuote.targetHighPrice || 0;
const targetLow = yahooQuote.targetLowPrice || 0;
const upsidePct = (targetMean > 0 && price > 0) ? ((targetMean - price) / price) * 100 : 0;

// --- Historical P&L ---
// Column Indices
const idx23 = getColIndexForYear("profit-loss", "2023");
const idx24 = getColIndexForYear("profit-loss", "2024");
const idx25 = getColIndexForYear("profit-loss", "2025");

// Sales
const revTTM = extractTableData("profit-loss", "Sales", -1);
const rev23 = extractTableData("profit-loss", "Sales", idx23);
const rev24 = extractTableData("profit-loss", "Sales", idx24);
const rev25 = extractTableData("profit-loss", "Sales", idx25);

// EBITDA
const ebitdaTTM = extractTableData("profit-loss", "Operating Profit", -1);
const ebitda23 = extractTableData("profit-loss", "Operating Profit", idx23);
const ebitda24 = extractTableData("profit-loss", "Operating Profit", idx24);
const ebitda25 = extractTableData("profit-loss", "Operating Profit", idx25);

// PAT
const patTTM = extractTableData("profit-loss", "Net Profit", -1);
const pat23 = extractTableData("profit-loss", "Net Profit", idx23);
const pat24 = extractTableData("profit-loss", "Net Profit", idx24);
const pat25 = extractTableData("profit-loss", "Net Profit", idx25);

// EPS
const epsTTM = extractTableData("profit-loss", "EPS", -1);
const eps23 = extractTableData("profit-loss", "EPS", idx23);
const eps24 = extractTableData("profit-loss", "EPS", idx24);
const eps25 = extractTableData("profit-loss", "EPS", idx25);

// --- Balance Sheet ---
const debt = extractTableData("balance-sheet", ["Borrowings", "Debt"], -1);
const cash = extractTableData("balance-sheet", ["Cash Equivalents", "Cash & Bank", "Cash &amp; Bank"], -1);
const reserves = extractTableData("balance-sheet", "Reserves", -1);
const shareCap = extractTableData("balance-sheet", "Share Capital", -1);
const assets = extractTableData("balance-sheet", "Fixed Assets", -1);
const cwip = extractTableData("balance-sheet", "CWIP", -1);

// --- Quarterly ---
const qSalesLat = extractTableData("quarters", "Sales", -1);
const qSalesPre = extractTableData("quarters", "Sales", -2);
const qSalesYear = extractTableData("quarters", "Sales", -5);
const qPatLat = extractTableData("quarters", "Net Profit", -1);
const qPatPre = extractTableData("quarters", "Net Profit", -2);
const qPatYear = extractTableData("quarters", "Net Profit", -5);
const qOpmLat = extractTableData("quarters", ["OPM %", "OPM"], -1);
const qOpLat = extractTableData("quarters", "Operating Profit", -1);
const qOpPre = extractTableData("quarters", "Operating Profit", -2);


// =====================================================
// 4. CALCULATIONS ENGINE
// =====================================================

// Ratios
const netWorth = (shareCap + reserves);
const netDebt = debt - cash;
const ev = (mCapCr || 0) + netDebt;
const deRatio = netWorth ? (debt / netWorth) : 0;
const assetTurn = (assets + cwip) ? (revTTM / (assets + cwip)) : 0;
const cwipRatio = assets ? (cwip / assets) : 0;
const numShares = (mCapCr && price) ? (mCapCr * 10000000) / price : 0;

// Margins
const ebitdaMargin25 = calcMargin(ebitda25, rev25);
const ebitdaMarginTTM = calcMargin(ebitdaTTM, revTTM);
const patMarginTTM = calcMargin(patTTM, revTTM);
const patMarginLat = calcMargin(qPatLat, qSalesLat);

// Growth Rates
const gQoQ_Rev = qSalesPre ? ((qSalesLat - qSalesPre)/qSalesPre)*100 : 0;
const gYoY_Sales = qSalesYear ? ((qSalesLat - qSalesYear)/qSalesYear)*100 : 0;
const gYoY_Pat = qPatYear ? ((qPatLat - qPatYear)/qPatYear)*100 : 0;
const gQoQ_Ebitda = qOpPre ? ((qOpLat - qOpPre)/qOpPre)*100 : 0;

// CAGR (Historical 2yr)
const cagrRev = calcCAGR(rev23, rev25, 2);
const cagrEbitda = calcCAGR(ebitda23, ebitda25, 2);
const cagrPat = calcCAGR(pat23, pat25, 2);
const cagrEps = calcCAGR(eps23, eps25, 2);

// Forward Projections (g = 12%)
const g = 1.12;
const rev26 = revTTM * g;
const rev27 = rev26 * g;
const rev28 = rev27 * g;
const pat26 = patTTM * g;
const pat27 = pat26 * g;
const pat28 = pat27 * g;
const ebitda26 = ebitdaTTM * g;
const ebitda27 = ebitda26 * g;
const ebitda28 = ebitda27 * g;
const eps26 = epsTTM * g;
const eps27 = eps26 * g;
const eps28 = eps27 * g;

// PE Forward
const pe26 = (eps26 && price) ? price / eps26 : 0;
const pe27 = (eps27 && price) ? price / eps27 : 0;
const pe28 = (eps28 && price) ? price / eps28 : 0;

// Charts
const chartBase = `https://finance.yahoo.com/quote/${nseCode}.NS/chart?p=${nseCode}.NS`;

// =====================================================
// 5. FINAL OUTPUT (EXACT SCHEMA MATCH)
// =====================================================
return [{
  json: {
    // Identity
    company_name: companyName,
    nse_code: nseCode,
    updated_at: new Date().toISOString(),

    // Market & Technicals
    market_cap: mCapCr,
    current_price: price,
    high_52_week: high52,
    low_52_week: low52,
    volume: vol,
    avg_50_day: yahooQuote.fiftyDayAverage || 0,
    avg_200_day: yahooQuote.twoHundredDayAverage || 0,

    // Returns
    return_1m: calcReturn(21),
    return_3m: calcReturn(63),
    return_6m: calcReturn(126),
    return_12m: calcReturn(252),
    return_down_from_52w_high: (high52 && price) ? ((price - high52)/high52)*100 : 0,
    return_up_from_52w_low: (low52 && price) ? ((price - low52)/low52)*100 : 0,

    // Links
    chart_url_1m: chartBase + "&range=1mo",
    chart_url_3m: chartBase + "&range=3mo",
    chart_url_6m: chartBase + "&range=6mo",
    chart_url_12m: chartBase + "&range=1y",

    // Analyst Targets (Filled)
    consensus_target_price: targetMean,
    consensus_upside_pct: upsidePct,
    target_price_high: targetHigh,
    target_price_low: targetLow,
    potential_upside_high: (targetHigh > price) ? ((targetHigh - price)/price)*100 : 0,
    potential_upside_low: (targetLow > 0) ? ((targetLow - price)/price)*100 : 0,

    // Valuation Ratios
    pe_ttm: yahooQuote.trailingPE || extractTopRatio("Stock P/E"),
    pe_fy2026e: pe26,
    pe_fy2027e: pe27,
    pe_fy2028e: pe28,
    ev_ebitda_ttm: ebitdaTTM ? (ev / ebitdaTTM) : 0,
    ps_ttm: revTTM ? (mCapCr / revTTM) : 0,
    book_value: extractTopRatio("Book Value"),
    dividend_yield: yahooQuote.dividendYield || extractTopRatio("Dividend Yield"),
    roe: extractTopRatio("ROE"),
    roce: extractTopRatio("ROCE"),
    face_value: extractTopRatio("Face Value"),

    // Balance Sheet Ratios
    debt: debt,
    cash_equivalents: cash,
    net_debt: netDebt,
    net_worth: netWorth,
    enterprise_value: ev,
    cwip: cwip,
    net_block: assets,
    cwip_to_net_block_ratio: cwipRatio,
    asset_turnover_ratio: assetTurn,
    debt_to_equity: deRatio,
    num_equity_shares: numShares,

    // Quarterly
    sales_latest_qtr: qSalesLat,
    op_profit_latest_qtr: qOpLat,
    pat_latest_qtr: qPatLat,
    ebitda_margin_latest_qtr: qOpmLat,
    pat_margin_latest_qtr: patMarginLat,
    sales_preceding_qtr: qSalesPre,
    op_profit_preceding_qtr: qOpPre,
    pat_preceding_qtr: qPatPre,

    // Growth
    revenue_growth_qoq: gQoQ_Rev,
    ebitda_growth_qoq: gQoQ_Ebitda,
    sales_growth_yoy_qtr: gYoY_Sales,
    profit_growth_yoy_qtr: gYoY_Pat,

    // Historicals
    revenue_fy2023: rev23,
    revenue_fy2024: rev24,
    revenue_fy2025: rev25,
    revenue_ttm: revTTM,
    sales_ttm_screener: revTTM,

    ebitda_fy2023: ebitda23,
    ebitda_fy2024: ebitda24,
    ebitda_fy2025: ebitda25,
    ebitda_ttm: ebitdaTTM,

    pat_fy2023: pat23,
    pat_fy2024: pat24,
    pat_fy2025: pat25,
    pat_ttm: patTTM,
    pat_ttm_screener: patTTM,

    eps_fy2023: eps23,
    eps_fy2024: eps24,
    eps_fy2025: eps25,
    eps_ttm: epsTTM,
    eps_ttm_actual: epsTTM,

    // Margins
    ebitda_margin_fy2025: ebitdaMargin25,
    ebitda_margin_ttm: ebitdaMarginTTM,
    opm_last_year: ebitdaMargin25,
    pat_margin_ttm: patMarginTTM,

    // Estimates
    revenue_fy2026e: rev26,
    revenue_fy2027e: rev27,
    revenue_fy2028e: rev28,
    ebitda_fy2026e: ebitda26,
    ebitda_fy2027e: ebitda27,
    ebitda_fy2028e: ebitda28,
    pat_fy2026e: pat26,
    pat_fy2027e: pat27,
    pat_fy2028e: pat28,
    eps_fy2026e: eps26,
    eps_fy2027e: eps27,
    eps_fy2028e: eps28,

    // CAGR
    revenue_cagr_hist_2yr: cagrRev,
    ebitda_cagr_hist_2yr: cagrEbitda,
    pat_cagr_hist_2yr: cagrPat,
    eps_cagr_hist_2yr: cagrEps,

    // Constant Growth Assumption
    revenue_cagr_fwd_2yr: 12, 
    ebitda_cagr_fwd_2yr: 12,
    pat_cagr_fwd_2yr: 12,
    eps_cagr_fwd_2yr: 12
  }
}];

// =====================================================
// 1. DATA SOURCES FUSION (The Gatekeeper)
// =====================================================
const screenerData = $node["HTTP Request1"]?.json?.data || "";
const yahooSpark = $node["HTTP Request2"]?.json?.spark?.result?.[0]?.response?.[0]?.meta || {};
const yahooChart = $node["HTTP Request"]?.json?.chart?.result?.[0] || {};
const yahooPrices = yahooChart?.indicators?.quote?.[0]?.close || [];

// =====================================================
// 2. HELPER FUNCTIONS
// =====================================================
function extractTopRatio(label) {
  if (!screenerData) return null;
  const regex = new RegExp(`${label}[\\s\\S]*?<span class="number">([0-9,.]+)`, "i");
  const match = screenerData.match(regex);
  return match ? parseFloat(match[1].replace(/,/g, "")) : null;
}

const calcReturn = (days) => {
  if (yahooPrices.length < days + 1) return 0;
  const curr = yahooPrices[yahooPrices.length - 1];
  const past = yahooPrices[yahooPrices.length - 1 - days];
  return (past && curr) ? ((curr - past) / past) * 100 : 0;
};

// =====================================================
// 3. LOGIC & MATH
// =====================================================
const price = yahooSpark.regularMarketPrice || 0;
const high52 = yahooSpark.fiftyTwoWeekHigh || 0;
const low52 = yahooSpark.fiftyTwoWeekLow || 0;
const nseCode = yahooSpark.symbol?.replace(".NS", "") || "TCS";

// Get Revenue TTM for Price-to-Sales calculation
const regexSales = /Sales[\s\S]*?<td[^>]*>([0-9,.]+)<\/td>/i;
const salesTTM = parseFloat(screenerData.match(regexSales)?.[1]?.replace(/,/g, "")) || 0;
const mCapCr = extractTopRatio("Market Cap") || 0;

// Projections for 2028
const g = 1.12; // 12% growth factor
const sales2028e = salesTTM * Math.pow(g, 3);
const ps2028e = sales2028e ? mCapCr / sales2028e : 0;

// Charts URL
const chartBase = `https://finance.yahoo.com/quote/${nseCode}.NS/chart`;

// =====================================================
// 4. FINAL OUTPUT (EXACT SUPABASE COLUMN NAMES)
// =====================================================
return [{
  json: {
    // Identity
    nse_code: nseCode,

    // Technicals & Returns (FIXING NULLS)
    return_1m: calcReturn(21),
    return_3m: calcReturn(63),
    return_6m: calcReturn(126),
    return_12m: calcReturn(252),
    return_down_from_52w_high: (high52 && price) ? ((price - high52) / high52) * 100 : 0,
    return_up_from_52w_low: (low52 && price) ? ((price - low52) / low52) * 100 : 0,

    // Valuation
    ps_fy2028e: ps2028e,

    // Analyst Targets (Defaults as Yahoo Spark doesn't have these)
    // We set to 0 instead of null so database is clean
    target_price_high: 0,
    target_price_low: 0,
    consensus_target_price: 0,
    consensus_upside_pct: 0,
    potential_upside_high: 0,
    potential_upside_low: 0,

    // Charts URLs
    chart_url_1m: chartBase + "?range=1mo",
    chart_url_3m: chartBase + "?range=3mo",
    chart_url_6m: chartBase + "?range=6mo",
    chart_url_12m: chartBase + "?range=1y",

    // Metadata
    updated_at: new Date().toISOString()
  }
}];

// 1. Get the Raw HTML
const html = items[0].json.data || "";

// --- HELPER FUNCTIONS ---

// Extract text between two markers
function extractBetween(startMarker, endMarker) {
  const startIndex = html.indexOf(startMarker);
  if (startIndex === -1) return null;
  const substring = html.substring(startIndex + startMarker.length);
  const endIndex = substring.indexOf(endMarker);
  if (endIndex === -1) return null;
  return substring.substring(0, endIndex).trim();
}

// Extract a clean number from a specific HTML label (Top Ratios)
function extractTopRatio(label) {
  // Regex: Label -> specific class structure -> number
  const regex = new RegExp(`${label}[\\s\\S]*?<span class="number">([0-9,.]+)`, "i");
  const match = html.match(regex);
  return match ? parseFloat(match[1].replace(/,/g, '')) : null;
}

// Extract Sector/Industry from Breadcrumbs
function extractBreadcrumb(title) {
  const regex = new RegExp(`href="[^"]+"[^>]*title="${title}">([^<]+)`, "i");
  const match = html.match(regex);
  return match ? match[1].trim() : null;
}

// Parse a Table by ID to get specific Row/Column data
function extractTableData(tableId, rowName, colIndex = -1) {
  // 1. Find the table
  const tableRegex = new RegExp(`section id="${tableId}"[\\s\\S]*?<table[\\s\\S]*?<\/table>`, "i");
  const tableMatch = html.match(tableRegex);
  if (!tableMatch) return null;
  const tableHtml = tableMatch[0];

  // 2. Find the Row
  // Matches row start -> rowName -> content up to next row start
  const rowRegex = new RegExp(`<tr[^>]*>[\\s\\S]*?${rowName}[\\s\\S]*?<\/tr>`, "i");
  const rowMatch = tableHtml.match(rowRegex);
  if (!rowMatch) return null;

  // 3. Extract all columns (td)
  const colRegex = /<td[^>]*>([\s\S]*?)<\/td>/gi;
  const cols = [...rowMatch[0].matchAll(colRegex)].map(m => m[1].replace(/<[^>]+>/g, '').trim());

  // 4. Return specific column
  // colIndex -1 = Last Column, -2 = Second to Last
  if (colIndex < 0) {
    return parseFloat(cols[cols.length + colIndex].replace(/,/g, '')) || 0;
  }
  return parseFloat(cols[colIndex].replace(/,/g, '')) || 0;
}

// Specific Extractor for Shareholding (often has different structure)
function extractShareholding(category) {
  const sectionRegex = /section id="shareholding"[\s\S]*?<\/table>/i;
  const sectionMatch = html.match(sectionRegex);
  if (!sectionMatch) return null;

  // Find row based on category (e.g., "Promoters")
  const rowRegex = new RegExp(`onclick="Company\\.showShareholders\\('${category}'[\\s\\S]*?<\/tr>`, "i");
  const rowMatch = sectionMatch[0].match(rowRegex);
  if (!rowMatch) return null;

  // Get last column value
  const tds = rowMatch[0].match(/<td>([0-9.]+)%<\/td>/gi);
  if (tds && tds.length > 0) {
    const lastVal = tds[tds.length - 1]; // Latest quarter
    return parseFloat(lastVal.replace(/[^0-9.]/g, ''));
  }
  return null;
}

// --- MAIN EXTRACTION ---

// 1. Identity & Sector
const companyName = extractBetween('<h1 class="margin-0 show-from-tablet-landscape">', '</h1>');
const sector = extractBreadcrumb("Sector");
const industry = extractBreadcrumb("Industry");
const bseCode = extractBetween('BSE:', '</span>').replace(/[^0-9]/g, '');
const nseCode = extractBetween('NSE:', '</span>').replace(/[^A-Z0-9]/g, ''); // Clean formatting

// 2. Top Ratios
const marketCap = extractTopRatio("Market Cap");
const currentPrice = extractTopRatio("Current Price");
const bookValue = extractTopRatio("Book Value");
const dividendYield = extractTopRatio("Dividend Yield");
const roe = extractTopRatio("ROE");
const roce = extractTopRatio("ROCE");
const faceValue = extractTopRatio("Face Value");

// High / Low is tricky, often combined: "4,161 / 2,867"
const highLowStr = extractBetween('High / Low', '</li>'); // Get the LI content
let high52 = null, low52 = null;
if (highLowStr) {
  const numbers = highLowStr.match(/[0-9,]+/g);
  if (numbers && numbers.length >= 2) {
    high52 = parseFloat(numbers[0].replace(/,/g, ''));
    low52 = parseFloat(numbers[1].replace(/,/g, ''));
  }
}

// 3. Quarterly Results (Latest & Preceding)
// Note: In your HTML, the table columns end at Dec 2025. 
// We grab the last column (-1) and the one before it (-2).
const salesQtrLatest = extractTableData("quarters", "Sales", -1);
const salesQtrPreceding = extractTableData("quarters", "Sales", -2);
const salesQtrYearAgo = extractTableData("quarters", "Sales", -5); // 4 quarters back for YoY

const opProfitQtrLatest = extractTableData("quarters", "Operating Profit", -1);
const opProfitQtrPreceding = extractTableData("quarters", "Operating Profit", -2);

const patQtrLatest = extractTableData("quarters", "Net Profit", -1);
const patQtrPreceding = extractTableData("quarters", "Net Profit", -2);
const patQtrYearAgo = extractTableData("quarters", "Net Profit", -5);

// 4. Profit & Loss (TTM)
// TTM is usually the last column in the P&L table
const salesTTM = extractTableData("profit-loss", "Sales", -1);
const opProfitTTM = extractTableData("profit-loss", "Operating Profit", -1);
const patTTM = extractTableData("profit-loss", "Net Profit", -1);
const epsTTM = extractTableData("profit-loss", "EPS", -1);

// 5. Balance Sheet (Latest Year)
const reserves = extractTableData("balance-sheet", "Reserves", -1);
const equityCapital = extractTableData("balance-sheet", "Equity Capital", -1);
const debt = extractTableData("balance-sheet", "Borrowings", -1);
const fixedAssets = extractTableData("balance-sheet", "Fixed Assets", -1);
const cwip = extractTableData("balance-sheet", "CWIP", -1);
// Investments often labeled "Investments"
const investments = extractTableData("balance-sheet", "Investments", -1);
// Cash often in "Other Assets" or explicit. In this HTML, "Other Assets" is huge (85k), likely includes Cash.
// Screener puts detailed cash in the popup of "Other Assets", but raw row is "Other Assets".
const otherAssets = extractTableData("balance-sheet", "Other Assets", -1); 

// 6. Shareholding
const promoterHolding = extractShareholding("promoters");

// --- CALCULATIONS ---

// Net Worth = Equity + Reserves
const netWorth = (equityCapital || 0) + (reserves || 0);

// Net Debt (Approx) = Borrowings - (Investments + Cash). 
// Note: On Screener, "Investments" + "Other Assets" often covers liquid assets, but "Other Assets" includes Receivables. 
// A safer simple Metric is just Debt. For Net Debt, you need "Cash Equivalents" which requires parsing the popup (not in this HTML).
// We will leave Net Debt null or just use Debt.

// Enterprise Value = MarketCap + Debt - Cash (Approx)
// Without exact Cash, we can't calculate precise EV, but we can store components.

// Growth Calcs
let revenueGrowthQoQ = 0;
if (salesQtrPreceding) {
  revenueGrowthQoQ = ((salesQtrLatest - salesQtrPreceding) / salesQtrPreceding) * 100;
}

let salesGrowthYoY = 0;
if (salesQtrYearAgo) {
  salesGrowthYoY = ((salesQtrLatest - salesQtrYearAgo) / salesQtrYearAgo) * 100;
}

let profitGrowthYoY = 0;
if (patQtrYearAgo) {
  profitGrowthYoY = ((patQtrLatest - patQtrYearAgo) / patQtrYearAgo) * 100;
}

// Margins
const ebitdaMarginTTM = salesTTM ? (opProfitTTM / salesTTM) * 100 : 0;
const patMarginTTM = salesTTM ? (patTTM / salesTTM) * 100 : 0;

// Estimates (The "Magic" 12% Growth Logic you liked)
const growthRate = 0.12; 
const revenueFY26 = salesTTM * (1 + growthRate);
const revenueFY27 = revenueFY26 * (1 + growthRate);
const patFY26 = patTTM * (1 + growthRate);
const epsFY26 = epsTTM * (1 + growthRate);
const peFY26 = (currentPrice && epsFY26) ? (currentPrice / epsFY26) : 0;

// --- FINAL OUTPUT MAPPING ---
return [{
  json: {
    // Identity
    company_name: companyName || "Unknown",
    nse_code: nseCode || $('Get a row').item.json.nse_code, // Fallback to input
    bse_code: bseCode,
    sector: sector,
    industry: industry,

    // Top Ratios
    market_cap: marketCap,
    current_price: currentPrice,
    high_52_week: high52,
    low_52_week: low52,
    book_value: bookValue,
    dividend_yield: dividendYield,
    roce: roce,
    roe: roe,
    face_value: faceValue,

    // Quarterly
    sales_latest_qtr: salesQtrLatest,
    sales_preceding_qtr: salesQtrPreceding,
    op_profit_latest_qtr: opProfitQtrLatest,
    op_profit_preceding_qtr: opProfitQtrPreceding,
    pat_latest_qtr: patQtrLatest,
    pat_preceding_qtr: patQtrPreceding,

    // Growth
    revenue_growth_qoq: revenueGrowthQoQ,
    sales_growth_yoy_qtr: salesGrowthYoY,
    profit_growth_yoy_qtr: profitGrowthYoY,

    // Annual / TTM
    sales_ttm: salesTTM, // Maps to sales_ttm_screener
    op_profit_ttm: opProfitTTM,
    pat_ttm: patTTM, // Maps to pat_ttm_screener
    eps_ttm: epsTTM,

    // Margins
    ebitda_margin_ttm: ebitdaMarginTTM,
    pat_margin_ttm: patMarginTTM,

    // Balance Sheet
    debt: debt,
    net_worth: netWorth,
    net_block: fixedAssets,
    cwip: cwip,

    // Shareholding
    promoter_holding_pct: promoterHolding,

    // Calculated Estimates (FY26/27)
    revenue_fy2026e: revenueFY26,
    revenue_fy2027e: revenueFY27,
    pat_fy2026e: patFY26,
    eps_fy2026e: epsFY26,
    pe_fy2026e: peFY26,

    // Metadata
    updated_at: new Date().toISOString()
  }
}];
